  "cờ sáng NIR ≥ {v}": ["NIR brightness flag ≥ {v}", "近红外亮度标记 ≥ {v}", "近紅外亮度標記 ≥ {v}"],
  "Khay trứng": ["Egg tray", "蛋盘", "蛋盤"],
