  "Lịch sử": ["History", "历史", "歷史"],
  "Pattern phổ đã biết": ["Known spectral patterns", "已知光谱模式", "已知光譜模式"],
  "dấu hiệu nhận biết · trứng khớp tự động": ["recognition signs · automatically matched eggs", "识别特征 · 自动匹配的蛋", "識別特徵 · 自動匹配的蛋"],
  "đột ngột": ["abrupt", "突然", "突然"],
