  "{b} · đầu {e} · z NIR {z}": ["{b} · {e} end · NIR z {z}", "{b} · {e}端 · 近红外 z {z}", "{b} · {e}端 · 近紅外 z {z}"],
  "Trứng khớp hiện tại:": ["Currently matching eggs:", "当前匹配的蛋：", "目前匹配的蛋："],
  "không có": ["none", "无", "無"],
  "Trứng tham chiếu:": ["Reference eggs:", "参考蛋：", "參考蛋："],
  "Dấu hiệu nhận biết qua phổ": ["Spectral recognition signs", "光谱识别特征", "光譜識別特徵"],
  "Chưa có pattern nào": ["No patterns yet", "尚无模式", "尚無模式"],
  "Khớp pattern:": ["Matches pattern:", "匹配模式：", "匹配模式："],
